mapper.update:
UPDATE interview_plan_drafts
SET status = 'FAILED',
    failure_reason = LEFT(#{failureReason}, 512),
    generation_deadline_at = NULL,
    updated_by = requested_by,
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{draftId}
  AND generation_message_id = #{messageId}
  AND COALESCE(attempt_count, 0) >= #{maxAttempts}
  AND (
      status = 'PENDING'
      OR (
          status = 'PROCESSING'
          AND (generation_deadline_at IS NULL OR generation_deadline_at <= #{now})
      )
  )

UPDATE interview_plan_drafts
SET status = 'FAILED',
    failure_reason = LEFT(#{failureReason}, 512),
    generation_deadline_at = NULL,
    updated_by = requested_by,
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{draftId}
  AND generation_message_id = #{messageId}
  AND attempt_count = #{attemptCount}
  AND status = 'PROCESSING'

UPDATE interview_plan_drafts
SET status = 'PENDING',
    generation_deadline_at = NULL,
    updated_by = requested_by,
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{draftId}
  AND generation_message_id = #{messageId}
  AND attempt_count = #{attemptCount}
  AND status = 'PROCESSING'

UPDATE interview_plan_drafts
SET status = 'EXPIRED',
    updated_at = #{now},
    trace_id = #{traceId}
WHERE id = #{draftId}
  AND status IN ('PENDING', 'PROCESSING', 'READY')
  AND expires_at IS NOT NULL
  AND expires_at <= #{now}
